&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt;Prix&lt;/b&gt; 1.800 po ; &lt;b&gt;Poids&lt;/b&gt; 37,5 kg  
&lt;b&gt;Bonus d&#39;armure&lt;/b&gt; +9 ; &lt;b&gt;Bonus de Dex maximal&lt;/b&gt; +1 ; &lt;b&gt;Malus d&#39;armure&lt;/b&gt; -6  
&lt;b&gt;Risque d&#39;&#233;chec des sorts profanes&lt;/b&gt; 35% ; &lt;b&gt;Vitesse&lt;/b&gt; 4,5 m/3 m (3 c/2 c)  
&lt;span class=&quot;Cat&#233;gorie&quot;&gt;&lt;b&gt;Cat&#233;gorie&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures.html#TABLOURDES&quot; title=&quot;Tableau r&#233;capitulatif des armures&quot;&gt;Armures lourdes&lt;/a&gt;&lt;/span&gt;
&lt;hr&gt;
&lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; width:250px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;Dans l&#39;&lt;u&gt;Art de la guerre&lt;/u&gt;, cet objet est aussi appel&#233; &quot;manteau de pierre&quot;.&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:30px; cursor:pointer&quot; src=&quot;/images/pathfinder/wiki/ibase.png&quot; title=&quot;Cliquez pour afficher/cacher une d&#233;sambigu&#239;sation (homonymes, redirections, etc...)&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
